/**
 * A default table cell renderer that relies on the <code>toString()</code> method when rendering
 * the cells of the table.
 */
public class GTableCellRenderer : AbstractGCellRenderer, TableCellRenderer {

	protected static readonly FormatSettingsDefinition INTEGER_RADIX_SETTING =
		FormatSettingsDefinition.DEF_DECIMAL;

	protected static readonly IntegerSignednessFormattingModeSettingsDefinition INTEGER_SIGNEDNESS_MODE_SETTING =
		IntegerSignednessFormattingModeSettingsDefinition.DEF;

	protected static readonly FloatingPointPrecisionSettingsDefinition FLOATING_POINT_PRECISION_SETTING =
		FloatingPointPrecisionSettingsDefinition.DEF;

	private static readonly Color BG_DRAG = new GColor("color.bg.table.row.drag");

	/*
	 * The map uses thread local variables to ensure that rendering and background model
	 * manipulation are thread safe.
	 */
	private static Map<Integer, ThreadLocal<DecimalFormat>> decimalFormatCache = new();
	static GTableCellRenderer() {

		int n = FloatingPointPrecisionSettingsDefinition.MAX_PRECISION;
		for (int i = 0; i <= n; i++) {
			int precision = i;
			ThreadLocal<DecimalFormat> localFormatter =
				ThreadLocal.withInitial(() => new DecimalFormat(createDecimalFormat(precision)));
			decimalFormatCache.put(precision, localFormatter);
		}
	}

	private ThemeListener themeListener = e => {
		if (e.isLookAndFeelChanged()) {
			updateUI();
		}
		else if (e.hasGlobalFontChanged()) {
			updateUI();
		}
	};

	/**
	 * Constructs a new GTableCellRenderer.
	 */
	public GTableCellRenderer() {
		// When the Look And Feel changes, renderers are not auto updated because they
		// are not part of the component tree. So listen for a change to the Look And Feel.
		Gui.addThemeListener(themeListener);
	}

	/**
	 * Constructs a new GTableCellRenderer using the specified font.
	 *
	 * @param f the font to use when rendering text in the table cells
	 */
	public GTableCellRenderer(Font f) : this()
    {
		setFont(f);
	}

	/**
	 * Return the cell renderer text
	 *
	 * @param value Cell object value
	 * @return A string interpretation of value; generated by calling value.toString()
	 */
	protected string getText(object value) {
		return value == null ? "" : value.toString();
	}

	/**
	 * Return the cell renderer text for the given rendering data.
	 * @param data the GTableCellRenderingData object that contains the object to render
	 * @return cell renderer text for the given rendering data. 
	 */
	protected string getText(GTableCellRenderingData data) {
		object value = data.getValue();
		if (value is Number n) {
			Settings settings = data.getColumnSettings();
			return formatNumber(n, settings);
		}
		return getText(value);
	}

	/**
	 * Satisfies the Java {@link javax.swing.table.TableCellRenderer} interface; retrieves column
	 * data via a GTableCellRenderingData object, and defers painting to
	 * {@link #getTableCellRendererComponent(GTableCellRenderingData)}.
	 * <p>
	 * This is marked <code>final</code> to redirect subclasses to the enhanced method,
	 * {@link #getTableCellRendererComponent(GTableCellRenderingData)}.
	 * <p>
	 * Throws an AssertException if the table this renderer is used with is not a
	 * {@link docking.widgets.table.GTable} instance.
	 *
	 * @see javax.swing.table.TableCellRenderer#getTableCellRendererComponent(javax.swing.JTable,
	 *      java.lang.Object, boolean, boolean, int, int)
	 * @see #getTableCellRendererComponent(GTableCellRenderingData)
	 */
	/* @Override */
	public Component getTableCellRendererComponent(JTable table, object value,
			bool isSelected, bool hasFocus, int row, int column) {

		if (!(table is GTable)) {
			throw new AssertException(
				"Using a GTableCellRenderer in a non-GTable table. (Model class: " +
					table.getModel().GetType().getName() + ")");
		}

		GTable gTable = (GTable) table;
		GTableCellRenderingData data = gTable.getRenderingData(column);
		object rowObject = null;

		if (gTable.getModel() is RowObjectTableModel) {
			rowObject = ((RowObjectTableModel<object>) gTable.getModel()).getRowObject(row);
		}

		data.setRowData(row, rowObject);
		data.setCellData(value, column, isSelected, hasFocus);

		Component renderComponent = getTableCellRendererComponent(data);

		data.resetRowData();

		return renderComponent;
	}

	/**
	 * Provide basic cell rendering -- setting foreground and background colors, font, text,
	 * alignment, drop color, and border. Additional data that may be of use to the renderer is
	 * passed through the {@link docking.widgets.table.GTableCellRenderingData} object.
	 *
	 * @param data Context data used in the rendering of a data cell.
	 * @return The component used for drawing the table cell.
	 */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		object value = data.getValue();
		JTable table = data.getTable();
		int row = data.getRowViewIndex();
		bool isSelected = data.isSelected();
		bool hasFocus = data.hasFocus();

		string text = getText(data);
		setText(text);

		int alignment = (value is Number) ? SwingConstants.RIGHT : SwingConstants.LEFT;
		setHorizontalAlignment(alignment);

		TableModel model = table.getModel();
		setFont(getDefaultFont());

		if (isSelected) {
			setForeground(table.getSelectionForeground());
			setBackground(table.getSelectionBackground());
			setOpaque(true);
		}
		else {
			setForegroundColor(table, model, value);

			if (row == dropRow) {
				setBackground(BG_DRAG);
			}
			else {
				setBackground(getAlternatingBackgroundColor(table, row));
			}
		}

		setBorder(hasFocus ? focusBorder : noFocusBorder);

		/*
		  	Before the following code changes, the default screen reader behavior was as follows
		  	when tabbing or arrowing through a table.
		  
		  		PE Header  selected  row 1  column 2			(a typical string column with text)
		  		PE Header  selected  row 1 Category column 2    (a string column with a truncated table header)
		  		selected  row 2  column 2						(an empty icon column)
		  		selected  false  row 1  column 1				(a boolean column)
		
			By default, the screen reader will read the cell's contents before describing the row, 
			column location.
			To make it more natural, we wanted to first read a description of the cell's column
			followed by the cell's contents.
		
		 */
		string accessibleValue = getAccessibleCellValue(data, text);
		getAccessibleContext().setAccessibleDescription(accessibleValue);
		string description = getAccessibleCellDescription(model, data.getColumnModelIndex());
		getAccessibleContext().setAccessibleName(description);

		return this;
	}

	/**
	 * Returns a string representation of the cell's value to be read by a screen reader. This
	 * does not have to exactly match the text in the table's cell.
	 * @param data the rendering data for the cell
	 * @param text the default text as it appears in the cell
	 * @return a string representation of the cell's value to be read by a screen reader
	 */
	protected string getAccessibleCellValue(GTableCellRenderingData data, string text) {
		return text;
	}

	/**
	 * Returns a description of the table's column to be read by a screen reader. By default it is
	 * the name of the column. The screen reader will read this string before reading the cell's 
	 * contents.
	 * @param model the table model
	 * @param columnModelIndex the column index
	 * @return a description of the table's column to be read by a screen reader
	 */
	protected string getAccessibleCellDescription(TableModel model, int columnModelIndex) {
		string columnName = model.getColumnName(columnModelIndex);
		return "Column: " + columnName;
	}

	protected void setForegroundColor(JTable table, TableModel model, object value) {
		setForeground(table.getForeground());
	}

	/**
	 * Override to change the font that will be used each time the renderer is initialized inside
	 * of {@link #getTableCellRendererComponent(GTableCellRenderingData)}
